    public int hashCode() {
        String str = "";
        str += bTGrpGroup7.hashCode();
        str += work.hashCode();
        str += bSGrp6.hashCode();
        str += bS7.hashCode();
        str += aS7.hashCode();
        str += aTGrpGroup7.hashCode();
        str += bTGroup6.hashCode();
       return str.hashCode();
    }

