    public int hashCode() {
        String str = "";
        str += aTGrpGroup8.hashCode();
        str += aSGrp9.hashCode();
        str += bTGrpGroup7.hashCode();
        str += work.hashCode();
        str += bTGrpGroup8.hashCode();
        str += aTGrpGroup9.hashCode();
       return str.hashCode();
    }

